import {seedItems,seedMissions,score} from '/js/modules/content.js';
import {loadLocal,saveLocal,localCatalog,escapeHTML as esc} from '/js/modules/state.js';
import * as cloud from '/js/firebase/service.js';
import {getFirebaseConfig} from '/js/config/firebase-config.js';
import {createWorld} from '/js/game/world.js';
let items=localCatalog(seedItems,'items'),missions=localCatalog(seedMissions,'missions'),state=loadLocal(),user=null,world,night=false,busy=false,saveTimer,lastCloudSave=0,cloudScore=null;
const $=s=>document.querySelector(s),modal=$('#modal'),content=$('#modalContent');let toastTimer;
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4500)}
function show(html){content.innerHTML=html;if(!modal.open)modal.showModal();world?.pause(true)}
function close(){modal.close();world?.pause(false)}$('.close').onclick=close;modal.addEventListener('cancel',()=>world?.pause(false));modal.addEventListener('click',e=>{if(e.target===modal)close()});
function render(){const count=state.ids.filter(id=>items.some(i=>i.id===id)).length;$('#score').innerHTML=`${cloudScore??score(state.ids,items,missions)} <small>XP</small>`;$('#count').textContent=count;$('#bagBadge').textContent=count;$('#progress').style.width=count/items.length*100+'%';$('#missionCount').textContent=missions.filter(m=>count>=m.required).length;const next=missions.find(m=>count<m.required);$('#nextName').textContent=next?.name||'นักประดิษฐ์แห่งอนาคต';$('#nextDescription').textContent=next?.description||'ยอดเยี่ยม! คุณค้นพบความรู้ครบทั้งเกาะแล้ว';$('#questCount').textContent=next?`${count} / ${next.required} ไอเทม`:'สำเร็จครบทุกภารกิจ';$('#questReward').textContent=next?`✦ +${next.reward} XP`:'✦ สำเร็จแล้ว';$('#questProgress').style.width=next?count/next.required*100+'%':'100%';$('#secondProgress').textContent=Math.min(count,6)+'/6'}
function knowledge(item,collected=false){show(`<div class="modal-eyebrow">${collected?'DISCOVERED · +'+item.points+' XP':'KNOWLEDGE JOURNAL'}</div><div class="modal-art">${seedItems.some(x=>x.id===item.id)?`<img src="/assets/images/${esc(item.id)}.svg" alt="ภาพประกอบ ${esc(item.title)}">`:esc(item.icon)}</div><small>${esc(item.zone)}</small><h2 class="modal-title">${esc(item.title)}</h2><p class="reading">${esc(item.body)}</p><div class="challenge"><b>✧ ชวนคิด ชวนออกแบบ</b><br>${esc(item.challenge)}</div><button class="primary" id="continue">${collected?'เก็บความรู้แล้ว · ผจญภัยต่อ →':'กลับไปสำรวจ →'}</button>`);$('#continue').onclick=close}
async function persist(){state.position=world?.position()||state.position;if(!user){try{saveLocal(state);$('#saveState').textContent='✓ บันทึกในอุปกรณ์แล้ว'}catch{toast('พื้นที่จัดเก็บเต็ม ไม่สามารถบันทึกในอุปกรณ์')}}else{try{await cloud.savePosition(user.uid,state.position);$('#saveState').textContent='✓ บันทึกบนคลาวด์แล้ว'}catch(e){$('#saveState').textContent='⚠ ยังไม่ซิงค์คลาวด์';toast('บันทึกคลาวด์ไม่สำเร็จ: '+e.message)}}}
async function collect(){const it=world?.nearest();if(!it||busy||modal.open)return;busy=true;$('#collect').disabled=true;try{if(user){const result=await cloud.collectCloud(it.id);state.ids=result.ids;cloudScore=result.score;world.setCollected(result.ids)}else{if(state.ids.includes(it.id))return;state.ids.push(it.id);world.collect(it.id)}await persist();render();knowledge(it,true);if(missions.some(m=>state.ids.length===m.required))toast('🏆 ภารกิจสำเร็จ! ได้รับรางวัล XP แล้ว')}catch(e){toast('เก็บไอเทมไม่สำเร็จ: '+e.message)}finally{busy=false;$('#collect').disabled=false}}
async function init(){try{if(getFirebaseConfig()){try{const [a,b]=await Promise.all([cloud.getCatalog('items'),cloud.getCatalog('missions')]);if(a.length)items=a;if(b.length)missions=b}catch{toast('โหลดเนื้อหาคลาวด์ไม่สำเร็จ ใช้เนื้อหาพื้นฐาน')}}world=createWorld($('#world'),items,it=>{$('#collect').hidden=!it;$('#collect').innerHTML=it?`<kbd>E</kbd> เก็บ ${esc(it.name)}`:''},pos=>{state.position=pos;$('#coords').textContent=`X: ${pos.x.toFixed(1)}　Z: ${pos.z.toFixed(1)}`;$('#miniPlayer').style.left=(pos.x+34)/68*88+'px';$('#miniPlayer').style.top=(pos.z+28)/56*70+'px';$('#zoneText').innerHTML=pos.z<-10?(pos.x>5?'โรงงานนักประดิษฐ์<small>INVENTOR WORKSHOP</small>':'ป่าแห่งการออกแบบ<small>DESIGN FOREST</small>'):(pos.x>8?'ห้องทดลอง AI<small>AI LABORATORY</small>':'หมู่บ้านนวัตกรรม<small>INNOVATION VILLAGE</small>');if(Date.now()-lastCloudSave>30000){lastCloudSave=Date.now();persist()}});world.setCollected(state.ids);world.restore(state.position);render();if(getFirebaseConfig())await cloud.observeUser(async u=>{user=u;if(u){try{const p=await cloud.loadPlayer(u.uid);state={ids:p.ids,position:p.position||{x:0,z:9}};world.setCollected(state.ids);world.restore(state.position);cloudScore=p.score;$('#playerName').innerHTML=`${esc(u.displayName||'นักสำรวจ')}<small>เชื่อมต่อ Google แล้ว · ออกจากระบบ ↗</small>`;$('#connection').textContent='● เชื่อมต่อ Firebase';render()}catch(e){toast('โหลดความคืบหน้าไม่สำเร็จ: '+e.message)}}else{$('#connection').textContent='● เล่นแบบผู้เยี่ยมชม'}})}catch(e){$('#gameError').hidden=false;$('#gameError').textContent='เปิดโลก 3D ไม่สำเร็จ กรุณาเปิด WebGL และโหลดหน้าใหม่: '+e.message}}
$('#start').onclick=()=>{world?.start();$('#startCallout').hidden=true;$('#minimap').style.display='block';toast('เดินด้วย WASD / ลูกศร · เข้าใกล้ไอเทมแล้วกด E')};$('#collect').onclick=collect;
window.addEventListener('keydown',e=>{if(modal.open)return;if(e.key.toLowerCase()==='e')collect();if(e.key.toLowerCase()==='i')view('inventory')});
for(const b of document.querySelectorAll('[data-key]')){b.onpointerdown=e=>{e.preventDefault();b.setPointerCapture(e.pointerId);world?.setKey(b.dataset.key,true)};b.onpointerup=b.onpointercancel=()=>world?.setKey(b.dataset.key,false)}
$('#login').onclick=async()=>{if(user){await persist();await cloud.signOut();location.reload();return}if(!getFirebaseConfig()){show('<div class="modal-eyebrow">SAVE YOUR ADVENTURE</div><h2 class="modal-title">เล่นได้เลยในโหมดผู้เยี่ยมชม</h2><p class="reading">ตำแหน่งและไอเทมจะบันทึกในเบราว์เซอร์นี้ การเข้าสู่ระบบ Google และเล่นต่อข้ามอุปกรณ์ต้องตั้งค่า Firebase ของโรงเรียนก่อน</p><a class="primary" href="/admin.html#settings">ตั้งค่า Firebase →</a>');return}try{await cloud.loginGoogle();toast('เข้าสู่ระบบแล้ว โหลดความคืบหน้าบนคลาวด์')}catch(e){toast('เข้าสู่ระบบไม่สำเร็จ: '+e.message)}};
async function view(v){if(v==='world'){close();return}if(v==='inventory'){show(`<div class="modal-eyebrow">YOUR COLLECTION</div><h2 class="modal-title">กระเป๋าไอเทม <small>${state.ids.length} / ${items.length}</small></h2>${state.ids.length?'<div class="list-grid">'+items.filter(i=>state.ids.includes(i.id)).map(i=>`<button class="list-card" data-read="${esc(i.id)}"><span class="icon">${esc(i.icon)}</span><b>${esc(i.name)}</b><p>${esc(i.title)}</p><small>อ่านความรู้อีกครั้ง →</small></button>`).join('')+'</div>':'<div class="empty"><span>▣</span>กระเป๋ายังว่างอยู่<br>เดินเข้าใกล้แสงสีทอง แล้วกด E เพื่อเก็บไอเทม</div>'}`)}if(v==='library'){show(`<div class="modal-eyebrow">KNOWLEDGE JOURNAL</div><h2 class="modal-title">สมุดความรู้ 12 หัวข้อ</h2><p class="reading">อ่านทบทวนได้ทุกเมื่อ คะแนนจะได้รับเมื่อค้นพบไอเทมในโลก 3D</p><div class="list-grid">${items.map(i=>`<button class="list-card" data-read="${esc(i.id)}"><span class="icon">${esc(i.icon)}</span><b>${esc(i.title)}</b><small>${state.ids.includes(i.id)?'✓ ค้นพบแล้ว':'◈ รอการค้นพบ'}</small></button>`).join('')}</div>`)}if(v==='missions'||v==='achievements'){show(`<div class="modal-eyebrow">${v==='missions'?'YOUR QUESTS':'ACHIEVEMENTS'}</div><h2 class="modal-title">${v==='missions'?'ภารกิจของฉัน':'เหรียญแห่งการเรียนรู้'}</h2><div class="list-grid">${missions.map((m,i)=>`<div class="list-card"><span class="icon">${state.ids.length>=m.required?'🏆':'⚑'}</span><b>${esc(m.name)}</b><p>${esc(m.description)}</p><small>${Math.min(state.ids.length,m.required)} / ${m.required} · +${m.reward} XP ${state.ids.length>=m.required?'✓ สำเร็จแล้ว':'· กำลังสำรวจ'}</small></div>`).join('')}</div>`)}if(v==='leaderboard'){show('<div class="modal-eyebrow">EXPLORER LEADERBOARD</div><h2 class="modal-title">กระดานคะแนน</h2><p class="reading">กำลังโหลด…</p>');if(!getFirebaseConfig()){content.innerHTML='<h2 class="modal-title">กระดานคะแนน</h2><p class="reading">เชื่อมต่อ Firebase และเข้าสู่ระบบเพื่อเปรียบเทียบคะแนนกับเพื่อน คะแนนผู้เยี่ยมชมแสดงเฉพาะในอุปกรณ์นี้</p><div class="list-card"><b>✦ นักสำรวจคนใหม่</b><p>'+score(state.ids,items,missions)+' XP · '+state.ids.length+' ไอเทม</p></div>';return}try{const rows=await cloud.leaderboard();content.innerHTML=`<h2 class="modal-title">กระดานคะแนน</h2><table><thead><tr><th>อันดับ</th><th>นักสำรวจ</th><th>XP</th></tr></thead><tbody>${rows.map((r,i)=>`<tr><td>${i+1}</td><td>${esc(r.displayName)}</td><td>${r.score}</td></tr>`).join('')}</tbody></table>${rows.length?'':'<p>ยังไม่มีผู้เล่นในกระดานคะแนน</p>'}`}catch(e){content.innerHTML='<p class="reading">โหลดคะแนนไม่สำเร็จ กรุณาเข้าสู่ระบบ Google ก่อน</p>'}}content.querySelectorAll('[data-read]').forEach(b=>b.onclick=()=>knowledge(items.find(i=>i.id===b.dataset.read)))}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>view(b.dataset.view));document.querySelectorAll('[data-topic]').forEach(b=>b.onclick=()=>knowledge(items.find(i=>i.id===b.dataset.topic)));$('#help').onclick=()=>show('<div class="modal-eyebrow">EXPLORER GUIDE</div><h2 class="modal-title">ออกผจญภัยอย่างไร?</h2><p class="reading">1. กด “เริ่มสำรวจ” เพื่อเริ่มเกม<br>2. เดินด้วย WASD หรือปุ่มลูกศร (บนมือถือใช้ปุ่มบนจอ)<br>3. เข้าใกล้คริสตัลสีทอง แล้วกด E หรือปุ่มเก็บไอเทม<br>4. อ่านความรู้และโจทย์ชวนคิด แล้วผจญภัยต่อ<br>5. กด I เพื่ออ่านทบทวนจากกระเป๋า<br><br>เดินข้ามแม่น้ำผ่านสะพานไม้ ภารกิจและเหรียญจะปลดล็อกอัตโนมัติเมื่อค้นพบไอเทมครบตามจำนวน บันทึกในอุปกรณ์ทุก 10 วินาที เมื่อเชื่อมต่อ Firebase จะบันทึกในบัญชีของคุณ</p>');$('#mapButton').onclick=()=>{$('#minimap').style.display=$('#minimap').style.display==='block'?'none':'block'};$('#fullscreen').onclick=()=>{if(document.fullscreenElement)document.exitFullscreen();else $('#viewport').requestFullscreen().catch(()=>toast('เบราว์เซอร์นี้ไม่รองรับเต็มหน้าจอ'))};$('#sound').onclick=()=>{night=!night;world?.night(night);$('#sound').innerHTML=night?'☾ <span>บรรยากาศยามเย็น</span>':'☀ <span>บรรยากาศกลางวัน</span>'};document.addEventListener('visibilitychange',()=>{if(document.hidden)persist()});init();
